{
  "name": "@fleetingecho/opencode-handoff",
  "version": "1.1.0",
  "type": "module",
  "description": "Persistent branch handoffs plus reviewed project-wide knowledge for OpenCode, stored outside the repository and shared with pi-handoff.",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/FleetingEcho/opencode-handoff.git"
  },
  "homepage": "https://github.com/FleetingEcho/opencode-handoff#readme",
  "bugs": {
    "url": "https://github.com/FleetingEcho/opencode-handoff/issues"
  },
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "*.ts",
    "skills",
    "README.md"
  ],
  "keywords": ["opencode", "opencode-plugin", "handoff", "memory", "coding-agent"],
  "exports": {
    ".": "./index.ts",
    "./server": "./index.ts"
  },
  "main": "./index.ts",
  "dependencies": {
    "@opencode-ai/plugin": "^1.18.10"
  },
  "//dependencies": "Exactly one runtime dependency: @opencode-ai/plugin is the only package imported for a value. The SDK, Node types, and TypeScript compiler are development-only.",
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "bun run test/port.test.ts",
    "check": "npm run typecheck && npm test",
    "pack:check": "npm pack --dry-run",
    "prepublishOnly": "npm run check"
  },
  "devDependencies": {
    "@opencode-ai/sdk": "^1.18.10",
    "@types/node": "^24.0.0",
    "typescript": "^5.9.3"
  }
}
